199	    ```typescript
200	    import { Component, input, output } from '@angular/core';
201	
202	    @Component({
203	      selector: 'app-property-filters',
204	      templateUrl: './property-filters.html'
205	    })
206	    export class PropertyFilters {
207	      properties = input.required<string[]>();
208	      disabled = input(false);
209	      filtersChanged = output<Record<string, string> | null>();
210	
211	      protected onSubmit(formEl: HTMLFormElement): void {
212	        const formData = new FormData(formEl);
213	        const filters: Record<string, string> = {};
214	        for (const name of this.properties()) {
215	          const value = (formData.get(name) as string | null)?.trim();
216	          if (value) {
217	            filters[name] = value;
218	          }
219	        }
220	        this.filtersChanged.emit(Object.keys(filters).length > 0 ? filters : null);
221	      }
222	    }
